select p.id,c.code,c.title,2,1 from public.ace_programmes p join public.ace_institutions i on i.id=p.institution_id and i.short_name='MUST' cross join (values ('BFB3201','Business Law'),('BFB3205','Public Relations'),('BFB3200','Human Resource Management'),('BFC3227','Cost Accounting'),('BFB3203','Leadership'),('BFB3202','Entrepreneurship')) c(code,title) where p.name='Bachelor of Business Administration' on conflict(programme_id,code) do nothing;