insert into public.ace_institutions(name,short_name) values ('Meru University of Science and Technology','MUST'),('Kenya Methodist University','KeMU'),('Mount Kenya University','MKU'),('Meru National Polytechnic','Meru NP'),('Mukiria Technical Training Institute','Mukiria TTI'),('Mitunguu Technical Training Institute','Mitunguu TTI'),('Karumo Technical Training Institute','Karumo TTI') on conflict(name) do nothing;
insert into public.ace_programmes(institution_id,name,school) select i.id,'Bachelor of Business Administration','School of Business and Economics' from public.ace_institutions i where i.short_name='MUST' on conflict(institution_id,name) do nothing;
